import maya.cmds as cmds
import maya.mel as mel

ns = self.namespace
geo = ns+"geo"

geo_list = [geo]
char_gr = cmds.listRelatives(geo, p=1)[0]

if cmds.listRelatives(char_gr, p=1):
    top_gr = cmds.listRelatives(char_gr, p=1)[0]
    if "main" in top_gr:
        for gr in cmds.listRelatives(top_gr):
            if gr != char_gr:
                geo_gr = gr.replace("main", "geo")
                if cmds.objExists(geo_gr):
                    geo_list.append(geo_gr)

root_name = self.main.get_root_name()
views = self.main.views[root_name]
sel = cmds.ls(sl=1)

def getSmooth():
    global geo
    for o in cmds.listRelatives(geo, allDescendents=1):
        shapes = cmds.listRelatives(o, s=1) or []
        for s in shapes:
            if 'scaleCube' in s:
                continue
            if not cmds.getAttr(s+'.intermediateObject'):
                smooth = 3 in cmds.displaySmoothness( s, q=True, polygonObject=True )
                return (smooth)

if cmds.objExists(geo):
    cmds.select(geo_list)
    if not getSmooth():
        cmds.displaySmoothness(divisionsU=0, divisionsV=3, pointsWire=16, pointsShaded=4, polygonObject=3)
    else:
        cmds.displaySmoothness(divisionsU=0, divisionsV=0, pointsWire=4, pointsShaded=1, polygonObject=1)

    if sel:
        cmds.select(sel)
    else:
        cmds.select(clear=1)


for view in views:
    for item in view.items:
        if item.name == "common_2_item_smooth" or item.name == "common_2_face_smooth":
            if getSmooth():
                item.text.set_text("3")
                item.set_color(QtGui.QColor(85, 170, 127, 255))
            else:
                item.text.set_text("1")
                item.set_color(QtGui.QColor(100, 130, 150, 255))



    self.view.scene().update()

