import maya.cmds as cmds
import maya.mel as mel

root_name = self.get_root_name()
ns = root_name.split("picker")[0]

def setState(part, item):
    global ns
    if cmds.objExists(ns+part+"_control.fkIk"):
        attr = ns+part+"_control.fkIk"
    else:
        attr = ns+part+"_control.ikFk"
    if cmds.getAttr(attr):
        item.text.set_text("IK")
        item.set_color(QtGui.QColor(160, 170, 120, 255))
    else:
        item.text.set_text("FK")
        item.set_color(QtGui.QColor(100, 130, 150, 255))

geo = ns+"geo"
def getSmooth():
    global geo
    for o in cmds.listRelatives(geo, allDescendents=1):
        shapes = cmds.listRelatives(o, s=1) or []
        for s in shapes:
            if 'scaleCube' in s:
                continue
            if not cmds.getAttr(s+'.intermediateObject'):
                smooth = 3 in cmds.displaySmoothness( s, q=True, polygonObject=True )
                return (smooth)

# cycle all items
views = self.views[root_name]
for view in views:
    for item in view.items:
        if item.name == "common_2_add_icon":
            v = cmds.getAttr(ns+'character.offsetControls')
            if v: item.polygon.opacity = 255
            else: item.polygon.opacity = 100
        elif item.name == "common_2_cloth_icon":
            v = cmds.getAttr(ns+'character.clothControls')
            if v: item.polygon.opacity = 255
            else: item.polygon.opacity = 100
        elif item.name == "common_2_face_icon":
            if cmds.objExists(ns+'character.bodyControls'):
                v = cmds.getAttr(ns+'character.bodyControls')
            else:
                v = cmds.getAttr(ns+'character.controls')
            if v: item.polygon.opacity = 255
            else: item.polygon.opacity = 100
        elif item.name == "common_2_face_face_icon":
            if cmds.objExists(ns+'character.FaceControls'):
                v = cmds.getAttr(ns+'character.FaceControls')
            else:
                v = cmds.getAttr(ns+'character.faceControls')
            if v: item.polygon.opacity = 255
            else: item.polygon.opacity = 100
        elif item.name == "common_2_face_plus_icon":
            if cmds.objExists(ns+'character.addFaceControls'):
                v = cmds.getAttr(ns+'character.addFaceControls')
                if v: item.polygon.opacity = 255
                else: item.polygon.opacity = 100

        elif item.name == "common_2_ikFk_arm":
            if cmds.objExists(ns+"l_arm_control"):
                setState("l_arm", item)
            else:
                setState("l_f_leg", item)

        elif item.name == "common_2_ikFk_arm_MIRROR":
            if cmds.objExists(ns+"l_arm_control"):
                setState("r_arm", item)
            else:
                setState("r_f_leg", item)

        elif item.name == "common_2_ikFk_leg":
            if cmds.objExists(ns+"l_leg_control"):
                setState("l_leg", item)
            else:
                setState("l_b_leg", item)

        elif item.name == "common_2_ikFk_leg_MIRROR":
            if cmds.objExists(ns+"r_leg_control"):
                setState("r_leg", item)
            else:
                setState("r_b_leg", item)

        elif item.name == "common_2_item_smooth" or item.name == "common_2_face_smooth":
            if cmds.objExists(ns+"geo"):
                if getSmooth():
                    item.text.set_text("3")
